async function rpcOk(api: Api, name: string, args: Record<string, unknown>) {
  const res = await api.rpc(name, args);
  const body = await res.text();
  expect(res.ok(), `${name}: ${res.status()} ${body}`).toBeTruthy();
  return JSON.parse(body);
}

/** Черновик симуляции с шагами 1–4 (как мастер S-08), возражение X1 свободным текстом. */
async function createSimulation(api: Api, name: string): Promise<string> {
  const created = await rpcOk(api, 'save_simulation', {
    p_simulation_id: null,
    p_fields: {
      name,
      role_title: 'נציג/ת מכירות טלפוני/ת QA-AUTO',
      industry: 'מערכות סולאריות',
      product_or_service: 'מערכת סולארית ביתית על הגג',
      target_audience: 'בעלי בתים פרטיים',
      call_goal: 'לקבוע פגישת ייעוץ בבית הלקוח',
      customer_type: 'warm_lead',
      language: 'he',
      duration_minutes: 7,
      desired_outcome: 'הלקוח מסכים לפגישת ייעוץ בבית',
      desired_next_step: 'consultation_meeting',
      end_conditions: null,
    },
  });
  const id = created.id as string;
  expect(created.status).toBe('draft');
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      customer_opening_state: 'סקרן אבל חשדן',
      customer_need: 'חשבון חשמל גבוה מאוד בקיץ',
      prior_relationship: null,
      info_items: [
        { text: 'בעל הבית גר בבית פרטי עם משפחה של חמש נפשות', tier: 'shown_upfront', reveal_condition: null },
        { text: 'באוגוסט שילם חשבון חשמל של אלף ושמונה מאות שקלים', tier: 'discover_in_call', reveal_condition: null },
      ],
    },
  });
  await saveFreeObjection(api, id, X1);
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      offer_allowed_info: 'אחריות של עשרים וחמש שנה על הפאנלים',
      offer_required_info: 'ההתקנה דורשת אישור חברת החשמל',
      offer_benefits: 'חיסכון בחשבון החשמל',
      offer_price: null,
      offer_forbidden_info: 'אין להמציא מענקים ממשלתיים',
      offer_forbidden_promises: 'אסור להבטיח החזר תוך שנה',
    },
  });
  return id;
}

async function saveFreeObjection(api: Api, id: string, o: typeof X1) {
  await rpcOk(api, 'save_simulation', {
    p_simulation_id: id,
    p_fields: {
      objection_source: 'free_text',
      main_objection: o.text,
      objection_reason: o.reason,
      objection_discoverable_info: o.discoverable_info,
      softening_conditions: o.softening_conditions,
      refusal_conditions: o.refusal_conditions,
    },
  });
}

/** Черновик сценария: по умолчанию ручной (save_scenario_draft), с QA_2B7F11_AI=1 — генерация AI. */
async function createScenarioDraft(page: Page, api: Api, id: string) {
  if (USE_AI) {
    const res = await page.request.post(`${SUPABASE_URL}/functions/v1/generate-scenario-draft`, {
      headers: api.headers,
      data: { simulation_id: id },
      timeout: 180_000,
    });
    const body = await res.text();
    expect(res.ok(), `generate-scenario-draft: ${res.status()} ${body}`).toBeTruthy();
    expect(JSON.parse(body).status, body).toBe('completed');
  } else {
    await rpcOk(api, 'save_scenario_draft', { p_simulation_id: id, p_fields: MANUAL_DRAFT });
  }
}

type Profile = {
  objection: { text: string; reason: string; discoverable_info: string; softening_conditions: string; refusal_conditions: string };
  scenario: Record<string, unknown> | null;
};

async function profile(api: Api, id: string): Promise<{ p: Profile; raw: string }> {
  const res = await api.rpc('get_behavior_profile', { p_simulation_id: id });
  const text = await res.text();
  expect(res.ok(), `get_behavior_profile: ${res.status()} ${text}`).toBeTruthy();
  const p = JSON.parse(text) as Profile;
  // Повторная сериализация: JSON.stringify не экранирует иврит, подсчёт текста по ней надёжен.
  return { p, raw: JSON.stringify(p) };
}

const countOf = (haystack: string, needle: string) => haystack.split(needle).length - 1;

/** Источник: «מה רצוי» — профиль держит одно возражение, равное источнику, во всех полях; AC тикета. */
async function expectSingleObjection(api: Api, id: string, oldText: string, newText: string, src: ObjectionSrc) {
  const { p, raw } = await profile(api, id);
  expect(countOf(raw, oldText), `старое возражение «${oldText}» осталось в профиле`).toBe(0);
  expect(p.objection.text).toBe(newText);
  expect(p.scenario, 'у профиля нет сценария').not.toBeNull();
  const s = p.scenario!;
  expect(s.main_objection, 'scenario.main_objection ≠ objection.text').toBe(newText);
  expect(p.objection.reason).toBe(src.reason);
  expect(s.objection_reason).toBe(src.reason);
  expect(s.softening_conditions).toBe(src.softening_conditions);
  expect(s.refusal_conditions).toBe(src.refusal_conditions);
  // Сгенерированное по старому возражению очищено и помечено к перегенерации (реализация фикса, 21.10).
  for (const k of GENERATED_KEYS) {
    const v = s[k];
    expect(v === undefined || v === null || v === '', `scenario.${k} не очищено: ${JSON.stringify(v)}`).toBeTruthy();
  }
  expect(s.needs_regeneration).toBe(true);
  expect([...((s.stale_generated_keys as string[]) ?? [])].sort()).toEqual([...GENERATED_KEYS].sort());
}

test.describe('Черновик сценария — правка главного возражения в источнике (#8d9759413c3e03a5762b7f11)', () => {
  test('правка возражения (свободный → свободный → библиотека → свободный): в профиле одно возражение, черновик требует перегенерации, «העברה לאישור» закрыта @desktop @data #8d9759413c3e03a5762b7f11', async ({ asUser }) => {
    test.setTimeout(USE_AI ? 300_000 : 120_000);
    const page = await asUser('business');
    await blockScenarioGeneration(page); // страница /draft не должна сама запускать AI
    const api = await openWithApi(page, '/simulations');
    const name = `QA-AUTO-2b7f11-${runStamp()}`;
    test.info().annotations.push({ type: 'test-data', description: `симуляция «${name}» (טיוטה), не удаляется` });

    const id = await test.step('симуляция с возражением X1 и черновиком сценария', async () => {
      const simId = await createSimulation(api, name);
      await createScenarioDraft(page, api, simId);
      const { p } = await profile(api, simId);
      expect(p.objection.text).toBe(X1.text);
      expect(p.scenario?.main_objection, 'контроль: черновик написан по X1').toBe(X1.text);
      expect(p.scenario?.needs_regeneration ?? false).toBe(false);
      return simId;
    });

    await test.step('свободный текст X1 → свободный текст X2: профиль = X2 во всех полях', async () => {
      await saveFreeObjection(api, id, X2);
      await expectSingleObjection(api, id, X1.text, X2.text, X2);
    });

    await test.step('S-09: предупреждение о перегенерации, в разделах — «ייכתב מחדש…», возражение X2', async () => {
      await page.goto(`/simulations/${id}/draft`);
      await expect(page.getByText('ההתנגדות המרכזית השתנתה מאז שהטיוטה נכתבה')).toBeVisible({ timeout: 30_000 });
      await expect(page.getByText('יש להפיק את הטיוטה מחדש לפני ההעברה לאישור').first()).toBeVisible();
      await expect(page.getByText('ייכתב מחדש לפי ההתנגדות המעודכנת').first()).toBeVisible();
      await expect(page.getByText(X2.text, { exact: true }).first()).toBeVisible();
      await expect(page.getByText(X1.text)).toHaveCount(0);
    });

    await test.step('«העברה לאישור» → 400 draft_needs_regeneration, «לא בוצע»', async () => {
      const submit = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/submit_simulation_for_approval'));
      await page.getByRole('button', { name: 'העברה לאישור' }).click();
      const res = await submit;
      const body = await res.text();
      expect(res.status(), body).toBe(400);
      expect(JSON.parse(body).message).toBe('draft_needs_regeneration');
      await expect(page.getByText('לא בוצע', { exact: true })).toBeVisible();
      await expect(page.getByText('ההתנגדות המרכזית השתנתה אחרי שהטיוטה נכתבה').first()).toBeVisible();
    });

    await test.step(`свободный текст X2 → библиотека «${LIBRARY_TEXT}»: профиль = пункт библиотеки`, async () => {
      const res = await api.get(`common_objections?select=id,text&status=eq.active&text=eq.${encodeURIComponent(LIBRARY_TEXT)}`);
      expect(res.ok(), `common_objections: ${res.status()}`).toBeTruthy();
      const rows = (await res.json()) as { id: string; text: string }[];
      expect(rows, `в библиотеке нет активного «${LIBRARY_TEXT}»`).toHaveLength(1);
      await rpcOk(api, 'save_simulation', {
        p_simulation_id: id,
        p_fields: {
          objection_source: 'library',
          objection_library_id: rows[0].id,
          objection_reason: LIB.reason,
          objection_discoverable_info: LIB.discoverable_info,
          softening_conditions: LIB.softening_conditions,
          refusal_conditions: LIB.refusal_conditions,
        },
      });
      await expectSingleObjection(api, id, X2.text, LIBRARY_TEXT, LIB);
    });

    await test.step('библиотека → свободный текст X3: профиль = X3', async () => {
      await saveFreeObjection(api, id, X3);
      await expectSingleObjection(api, id, LIBRARY_TEXT, X3.text, X3);
    });
  });
});
